function switchActiveSbu(id,view){if(!portfolio.sbus[id])return;activate(id);plan={};uploadSelection.sbu=id;uploadTarget=null;productSelection='';planningBase='';try{localStorage.setItem('agi-active-sbu',id);}catch{}if(view){state.view=view;location.hash=view;}$('evidence')?.close();render();}
const interactiveChart=reviewChart,hiddenChartSeries=new Set();
reviewChart=function(title,series,labels,format){const key=activeSbu+'|'+title,display=series.map((s,i)=>({...s,values:hiddenChartSeries.has(key+'|'+i)?s.values.map(()=>null):s.values}));return interactiveChart(title,display,labels,format)+`<div class="chart-series-controls" aria-label="Show or hide chart series">${series.map((s,i)=>`<button class="series-toggle" data-series-key="${esc(key+'|'+i)}" aria-pressed="${!hiddenChartSeries.has(key+'|'+i)}">${esc(s.name)}</button>`).join('')}</div>`;};
const interactiveGroup=groupView;groupView=function(){let html=interactiveGroup();for(const [id,s]of Object.entries(portfolio.sbus))html=html.replace('<td>'+esc(s.name)+'</td>',`<td><button data-open-sbu="${esc(id)}" aria-label="Open ${esc(s.name)} performance">${esc(s.name)}${id===activeSbu?' · Active':''}</button></td>`);return html;};
function enhanceReviewTables(){document.querySelectorAll('#content table').forEach((table,index)=>{const body=table.tBodies[0],head=table.tHead;if(!body||!head)return;const rows=[...body.rows];if(rows.length<2)return;const title=table.closest('section')?.querySelector('h2')?.textContent||'Table';[...head.rows[0].cells].forEach((cell,col)=>{const label=cell.textContent,button=document.createElement('button');button.type='button';button.className='sort-column';button.textContent=label+' ↕';button.setAttribute('aria-label','Sort '+title+' by '+label);cell.replaceChildren(button);let direction=1;button.onclick=()=>{const parse=r=>{const text=r.cells[col]?.textContent.trim()||'';if(!text||text==='—')return null;const raw=text.replace(/,/g,'').replace(/\s*(%|×|MT|BDT.*)$/,'');return /^[-+]?\d+(\.\d+)?$/.test(raw)?Number(raw):text;};rows.sort((a,b)=>{const av=parse(a),bv=parse(b);if(av===null)return bv===null?0:1;if(bv===null)return-1;return direction*(typeof av==='number'&&typeof bv==='number'?av-bv:String(av).localeCompare(String(bv),undefined,{numeric:true}));});rows.forEach(r=>body.appendChild(r));head.querySelectorAll('th').forEach(h=>h.removeAttribute('aria-sort'));cell.setAttribute('aria-sort',direction===1?'ascending':'descending');direction*=-1;};});if(rows.length>=8){const field=document.createElement('input');field.type='search';field.className='table-search';field.placeholder='Search '+title;field.setAttribute('aria-label','Search '+title);field.oninput=()=>{const query=field.value.trim().toLowerCase();rows.forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(query));};table.parentElement.before(field);}});}
const interactiveRender=render;render=function(){interactiveRender();if(!data)return;$('sbuControls').innerHTML=`<div class="active-sbu-label">Active SBU</div><div class="active-sbu-options">${Object.entries(portfolio.sbus).map(([id,s])=>`<button class="sbu-choice ${id===activeSbu?'selected':''}" data-active-sbu="${esc(id)}" aria-pressed="${id===activeSbu}" title="${esc(s.name)}">${esc(s.code||s.name)}${id===activeSbu?' <span aria-hidden="true">✓</span>':''}</button>`).join('')}</div><div class="active-sbu-name">${esc(portfolio.sbus[activeSbu].name)}</div>`;document.querySelectorAll('[data-active-sbu]').forEach(e=>e.onclick=()=>switchActiveSbu(e.dataset.activeSbu));if($('sbu'))$('sbu').onchange=e=>switchActiveSbu(e.target.value);document.querySelectorAll('[data-open-sbu]').forEach(e=>e.onclick=()=>switchActiveSbu(e.dataset.openSbu,'overview'));document.querySelectorAll('[data-series-key]').forEach(e=>e.onclick=()=>{const key=e.dataset.seriesKey;hiddenChartSeries.has(key)?hiddenChartSeries.delete(key):hiddenChartSeries.add(key);render();});document.querySelectorAll('#nav [data-view]').forEach(e=>{if(e.dataset.view===state.view)e.setAttribute('aria-current','page');else e.removeAttribute('aria-current');});enhanceReviewTables();};
if(typeof window!=='undefined')window.addEventListener('hashchange',()=>{const view=location.hash.slice(1);if(views[view]&&view!==state.view){state.view=view;render();}});
